def _canonicalize_name(prefix, qvm_type, noisy):
    """Take the output of _parse_name to create a canonical name.
    """
    if noisy:
        noise_suffix = '-noisy'
    else:
        noise_suffix = ''

    if qvm_type is None:
        qvm_suffix = ''
    elif qvm_type == 'qvm':
        qvm_suffix = '-qvm'
    elif qvm_type == 'pyqvm':
        qvm_suffix = '-pyqvm'
    else:
        raise ValueError(f"Unknown qvm_type {qvm_type}")

    name = f'{prefix}{noise_suffix}{qvm_suffix}'
    return name

