                      sentence_variables: Dict[str, str]) -> Tuple[List[str], List[str]]:
    """
    Replaces abstract variables in text with their concrete counterparts.
    """
    tokens = []
    tags = []
    for token in sentence:
        if token not in sentence_variables:
            tokens.append(token)
            tags.append("O")
        else:
            for word in sentence_variables[token].split():
                tokens.append(word)
                tags.append(token)
    return tokens, tags

def _get_fault_dip_term(self, C, rup):
        """
        Returns the fault dip term, defined in equation 24
        """
        if rup.mag < 4.5:
            return C["c19"] * rup.dip
        elif rup.mag > 5.5:
            return 0.0
        else:
            return C["c19"] * (5.5 - rup.mag) * rup.dip

